      "summary": {
        "defaultLocale": "en-US",
        "defaultText": "The NIST coverage package emits supported OSCAL Assessment Results and declares unsupported federal package artifacts separately.",
        "icuArgs": {},
        "msgid": "scribe.report.nistCoverage.finding.example.summary",
        "provenance": "template",
        "reviewState": "reviewed",
        "values": {
          "cy-GB": {
            "fallback": false,
            "reviewed": true,
            "text": "Mae'r pecyn cwmpasu NIST yn rhyddhau Canlyniadau Asesiad OSCAL a gynhelir ac yn datgan arteffactau pecynnau llywodraethol na chynhelir ar wahân."
          },
          "de-DE": {
            "fallback": false,
            "reviewed": true,
            "text": "Das NIST-Abdeckungspaket gibt unterstützte OSCAL-Bewertungsergebnisse aus und deklariert nicht unterstützte Bundespaketartefakte separat."
          },
          "en-CA": {
            "fallback": false,
            "reviewed": true,
            "text": "The NIST coverage package emits supported OSCAL Assessment Results and declares unsupported federal package artifacts separately."
          },
          "en-GB": {
            "fallback": false,
            "reviewed": true,
            "text": "The NIST coverage package emits supported OSCAL Assessment Results and declares unsupported federal package artifacts separately."
          },
          "en-IN": {
            "fallback": false,
            "reviewed": true,
            "text": "The NIST coverage package emits supported OSCAL Assessment Results and declares unsupported federal package artifacts separately."
          },
          "en-US": {
            "fallback": false,
            "reviewed": true,
            "text": "The NIST coverage package emits supported OSCAL Assessment Results and declares unsupported federal package artifacts separately."
          },
          "es-ES": {
            "fallback": false,
            "reviewed": true,
            "text": "El paquete de cobertura del NIST emite los resultados de evaluación de OSCAL admitidos y declara los artefactos de paquete federal no admitidos por separado."
          },
          "es-MX": {
            "fallback": false,
            "reviewed": true,
            "text": "El paquete de cobertura NIST emite Resultados de Evaluación OSCAL compatibles y declara por separado los artefactos federales no compatibles."
          },
          "es-US": {
            "fallback": false,
            "reviewed": true,
            "text": "El paquete de cobertura NIST emite Resultados de Evaluación OSCAL compatibles y declara por separado los artefactos federales no compatibles."
          },
          "fr-CA": {
            "fallback": false,
            "reviewed": true,
            "text": "Le package de couverture NIST émet les résultats d'évaluation OSCAL pris en charge et déclare séparément les artefacts de package fédéraux non pris en charge."
          },
          "fr-FR": {
            "fallback": false,
            "reviewed": true,
            "text": "Le package de couverture NIST émet les résultats d'évaluation OSCAL pris en charge et déclare séparément les artefacts de package fédéraux non pris en charge."
          },
          "ga-GB": {
            "fallback": false,
            "reviewed": true,
            "text": "Eisíonn an pacáiste clúdach NIST Torthaí Measúnaithe OSCAL tacaíochta agus dearbhaíonn sé artifacts pacáiste cónaidhme gan tacaíocht ar leithligh."
          },
          "gd-GB": {
            "fallback": false,
            "reviewed": true,
            "text": "Bidh am pacaid còmhdaidh NIST a' cur a-mach toraidhean measadh OSCAL a tha air an taic agus a' dearbhadh nithean pacaid feadarail nach eil air an taic air leth."
          },
          "hi-IN": {
            "fallback": false,
            "reviewed": true,
            "text": "NIST कवरेज पैकेज समर्थित OSCAL मूल्यांकन परिणामों को जारी करता है और अलग से असमर्थित संघीय पैकेज आर्टिफैक्ट्स की घोषणा करता है।"
          },
          "it-IT": {
            "fallback": false,
            "reviewed": true,
            "text": "Il pacchetto di copertura NIST emette i risultati di valutazione OSCAL supportati e dichiara separatamente gli artefatti del pacchetto federale non supportati."
          },
          "ja-JP": {
            "fallback": false,
            "reviewed": true,
            "text": "NIST カバレッジパッケージは、サポート対象の OSCAL Assessment Results を出力し、未サポートの連邦パッケージ成果物を別途宣言します。"
          },
          "ko-KR": {
            "fallback": false,
            "reviewed": true,
            "text": "NIST 커버리지 패키지는 지원되는 OSCAL 평가 결과를 발행하고 지원되지 않는 연방 패키지 아티팩트를 별도로 선언합니다."
          },
          "kw-GB": {
            "fallback": false,
            "reviewed": true,
            "text": "An paket koveryans NIST a dherivas an OSCAL Assessment Results a vydh skosys ha'n artifacts federal a paketow na vydh skosys a-ves."
          },
          "nl-NL": {
            "fallback": false,
            "reviewed": true,
            "text": "Het NIST-dekkingspakket geeft ondersteunde OSCAL-beoordelingsresultaten uit en verklaart niet-ondersteunde federale pakketartefacten afzonderlijk."
          },
          "pl-PL": {
            "fallback": false,
            "reviewed": true,
            "text": "Pakiet zasięgu NIST wydaje obsługiwane wyniki oceny OSCAL i deklaruje oddzielnie nieobsługiwane artefakty pakietów federalnych."
          },
          "pt-BR": {
            "fallback": false,
            "reviewed": true,
            "text": "O pacote de cobertura NIST emite os resultados de avaliação OSCAL suportados e declara artefatos de pacote federal não suportados separadamente."
          },
          "pt-PT": {
            "fallback": false,
            "reviewed": true,
            "text": "O pacote de cobertura NIST emite os resultados de avaliação OSCAL suportados e declara artefatos de pacote federal não suportados separadamente."
          },
          "ro-RO": {
            "fallback": false,
            "reviewed": true,
            "text": "Pachetul de acoperire NIST emite rezultatele de evaluare OSCAL acceptate și declară separat artefactele pachetului federal neacceptate."
          },
          "sco-GB": {
            "fallback": false,
            "reviewed": true,
            "text": "The NIST coverage package emits supportit OSCAL Assessment Results and declares unsupportit federal package artifacts separate."
          },
          "sv-SE": {
            "fallback": false,
            "reviewed": true,
            "text": "NIST-täckningspaketet utfärdar OSCAL-utvärderingsresultat som stöds och deklarerar separat artefakter i federala paket som inte stöds."
          },
          "zh-CN": {
            "fallback": false,
            "reviewed": true,
            "text": "NIST 覆盖包发送受支持的 OSCAL 评估结果,并单独声明不受支持的联邦包工件。"
          }
        }
      },
